<?php $page='gallery'; $title='Gallery'; require __DIR__ . '/includes/header.php'; $photos = db()->query('SELECT * FROM gallery ORDER BY created_at DESC')->fetchAll(); ?>
<section class="section"><p class="kicker">Campus</p><h1>Institute gallery</h1><p class="lede">Classrooms, assembly, events and scholarship day. Nayi photos admin panel se upload hoti hain.</p></section>
<section class="section"><?php if (!$photos): ?><p class="empty">Abhi koi photo nahi. Facebook page par aur photos hain: <a href="<?= e(setting('facebook')) ?>">school Facebook</a>.</p><?php else: ?><div class="gallery-grid"><?php foreach ($photos as $photo): ?><figure><img src="<?= e(asset('uploads/gallery/' . $photo['filename'])) ?>" alt="<?= e($photo['title']) ?>"><figcaption><?= e($photo['title']) ?></figcaption></figure><?php endforeach; ?></div><?php endif; ?></section>
